package main

import (
	"context"
	"fmt"
	"os"

	"entire.io/cmd/entiredb/cli"
	_ "entire.io/internal/gogitzlib" // registers klauspost zlib provider with go-git
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	config, err := cli.LoadConfig()
	if err != nil {
		return fmt.Errorf("loading config: %w", err)
	}

	rootCmd := cli.NewPluginRootCmd(config)
	ctx := context.Background()

	return rootCmd.ExecuteContext(ctx) //nolint:wrapcheck // no need to prepend any text
}
package cli

import (
	"fmt"
	"io"
	"sort"

	"github.com/spf13/cobra"
	"github.com/spf13/cobra/doc"
)

func newDocsCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "docs",
		Short: "Print full CLI reference as Markdown to stdout",
		Long: "Dumps every subcommand's description, flags, and examples in a " +
			"single Markdown stream, generated from the live command tree. " +
			"Pipe into an LLM context so agents work from real command " +
			"definitions instead of guessing.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			root := cmd.Root()
			root.DisableAutoGenTag = true
			return walkDocs(root, cmd.OutOrStdout())
		},
	}
}

func walkDocs(cmd *cobra.Command, w io.Writer) error {
	if err := doc.GenMarkdown(cmd, w); err != nil {
		return fmt.Errorf("render docs for %q: %w", cmd.CommandPath(), err)
	}
	children := cmd.Commands()
	sort.Slice(children, func(i, j int) bool { return children[i].Name() < children[j].Name() })
	for _, c := range children {
		if !c.IsAvailableCommand() || c.Name() == "help" || c.Name() == "completion" {
			continue
		}
		if err := walkDocs(c, w); err != nil {
			return err
		}
	}
	return nil
}
package cli

import (
	"context"
	"fmt"
	"net/http"

	"entire.io/gen/openapi/entiredb"
)

// newEntireDBClient returns a generated OpenAPI client for baseURL, pre-wired
// with a bearer-auth request editor and the shared TLS policy.
func newEntireDBClient(baseURL, token string, skipTLSVerify bool) (*entiredb.ClientWithResponses, error) {
	bearer := func(_ context.Context, req *http.Request) error {
		req.Header.Set("Authorization", "Bearer "+token)
		return nil
	}
	c, err := entiredb.NewClientWithResponses(
		baseURL,
		entiredb.WithHTTPClient(newHTTPClient(skipTLSVerify)),
		entiredb.WithRequestEditorFn(bearer),
	)
	if err != nil {
		return nil, fmt.Errorf("build API client: %w", err)
	}
	return c, nil
}
