package cli

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"net/url"
	"os"

	"google.golang.org/grpc"

	"entire.io/client"
	"entire.io/client/discovery"
	"entire.io/tlscert"
)

// errResolveCacheMiss is returned from inside the cached-host attempt when
// Resolve fails on a cached replica, signalling the caller to invalidate the
// cache entry and fall back to the configured host. It must not escape
// connectForRepo.
var errResolveCacheMiss = errors.New("resolve failed on cached replica")

// connectForRepo opens an authenticated client for a repo-scoped operation
// and hands fn a configured *client.Client plus the resolved repo ULID.
//
// The helper consults the on-disk replica cache (shared with
// git-remote-entire), keyed by ENTIRE_BASE_URL host + repo path, and dials a
// hosting replica when known. Cache miss / stale entry / cached host
// unreachable all fall back to cfg.EntireHost; the fallback Resolve sets
// include_replicas so the next call gets affinity.
//
// ENTIRE_TOKEN, when set, bypasses the credential store and is sent on every
// dial — useful when the keyring is broken or for CI workloads injecting a
// JWT directly.
func connectForRepo(cfg Config, repoPath string, fn func(c *client.Client, repoID string) error) error {
	grpcOpts := tlscert.GRPCClientCredentials(cfg.SkipTLSVerify)

	connect, err := repoConnectFunc(cfg, grpcOpts)
	if err != nil {
		return err
	}

	host := cfg.EntireHost
	cacheDir := discovery.DefaultCacheDir()

	if cachedHost, ok := pickCachedReplicaHost(cacheDir, host, repoPath); ok {
		err := connect(cachedHost, func(c *client.Client) error {
			repoID, rerr := c.RepoResolve(context.Background(), repoPath)
			if rerr != nil {
				return fmt.Errorf("%w: %w", errResolveCacheMiss, rerr)
			}
			return fn(c, repoID)
		})
		if !errors.Is(err, errResolveCacheMiss) {
			if err != nil {
				return fmt.Errorf("dial cached replica %s: %w", cachedHost, err)
			}
			return nil
		}
		invalidateCachedReplicas(cacheDir, host, repoPath)
	}

	if err := connect(cfg.EntireHost, func(c *client.Client) error {
		repoID, replicas, rerr := c.RepoResolveWithReplicas(context.Background(), repoPath)
		if rerr != nil {
			return fmt.Errorf("resolve %q: %w", repoPath, rerr)
		}
		if len(replicas) > 0 {
			storeCachedReplicas(cacheDir, host, repoPath, replicas)
		}
		return fn(c, repoID)
	}); err != nil {
		return fmt.Errorf("dial %s: %w", cfg.EntireHost, err)
	}
	return nil
}

// repoConnectFunc returns a connector for a repo-scoped op. ENTIRE_TOKEN, when
// set, attaches the literal JWT and bypasses the credential store. Otherwise
// the helper resolves a context (binding for cfg.EntireHost, else current),
// uses its keychain slot, and wires up the auto-refresh interceptor.
func repoConnectFunc(cfg Config, grpcOpts grpc.DialOption) (func(target string, fn client.ConnFunc) error, error) {
	if envToken := os.Getenv("ENTIRE_TOKEN"); envToken != "" {
		return func(target string, fn client.ConnFunc) error {
			return client.ConnectWithAuth(target, envToken, fn, grpcOpts)
		}, nil
	}

	c, err := resolveContext(cfg)
	if err != nil {
		return nil, err
	}

	authCfg := client.AuthInterceptorConfig{
		KeyringService: c.KeychainService,
		BaseURL:        cfg.EntireBaseURL,
		Username:       c.Handle,
		CoreBaseURL:    c.CoreURL,
		HTTPClient:     newHTTPClient(cfg.SkipTLSVerify),
	}
	return func(target string, fn client.ConnFunc) error {
		return client.ConnectWithRefresh(target, authCfg, fn, grpcOpts)
	}, nil
}

// pickCachedReplicaHost reads the disk cache and returns a random fresh
// replica's host:port for gRPC dial. The second return value is false when
// the cache is missing, stale, or contains no parsable URIs.
func pickCachedReplicaHost(cacheDir, host, repoPath string) (string, bool) {
	cache, err := discovery.LoadCache(cacheDir)
	if err != nil {
		return "", false
	}
	uris, fresh := cache.GetRepoNodes(host, repoPath)
	if !fresh || len(uris) == 0 {
		return "", false
	}
	uri := uris[rand.IntN(len(uris))] //nolint:gosec // load-spreading, not security
	target, err := replicaURIToGRPCHost(uri)
	if err != nil {
		return "", false
	}
	return target, true
}

// storeCachedReplicas writes a fresh replica set into the disk cache,
// best-effort. Errors are ignored — a missing cache write only costs the
// next invocation one extra round-trip through the LB.
func storeCachedReplicas(cacheDir, host, repoPath string, replicas []string) {
	cache, err := discovery.LoadCache(cacheDir)
	if err != nil {
		return
	}
	cache.SetRepoNodes(host, repoPath, replicas, discovery.DefaultTTL)
	_ = discovery.SaveCache(cacheDir, cache) //nolint:errcheck // best-effort
}

// invalidateCachedReplicas drops the cache entry for a repo, best-effort.
func invalidateCachedReplicas(cacheDir, host, repoPath string) {
	cache, err := discovery.LoadCache(cacheDir)
	if err != nil {
		return
	}
	cache.InvalidateRepo(host, repoPath)
	_ = discovery.SaveCache(cacheDir, cache) //nolint:errcheck // best-effort
}

// replicaURIToGRPCHost converts an https://host[:port] URI to a gRPC dial
// target ("host:port", with port 443 implied for https when absent).
func replicaURIToGRPCHost(uri string) (string, error) {
	u, err := url.Parse(uri)
	if err != nil || u.Host == "" {
		return "", fmt.Errorf("invalid replica URI %q", uri)
	}
	if u.Port() != "" {
		return u.Host, nil
	}
	switch u.Scheme {
	case "https":
		return u.Host + ":443", nil
	case "http":
		return u.Host + ":80", nil
	default:
		return "", fmt.Errorf("unsupported replica URI scheme %q in %q", u.Scheme, uri)
	}
}
