32	// ConnectWithAPIKey connects using a preshared API key sent via the X-Entire-Api-Auth header.
33	func ConnectWithAPIKey(host, apiKey string, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
34		grpcOpts = append([]grpc.DialOption{
35			grpc.WithUnaryInterceptor(apiKeyInterceptor(apiKey)),
36		}, grpcOpts...)
37	
38		conn, err := grpc.NewClient(host, grpcOpts...)
39		if err != nil {
40			return fmt.Errorf("connecting to server: %w", err)
41		}
42		defer func() {
43			if closeErr := conn.Close(); closeErr != nil {
44				fmt.Printf("Warning: failed to close gRPC connection: %v\n", closeErr)
45			}
