56	func apiKeyInterceptor(apiKey string) grpc.UnaryClientInterceptor {
57		return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
58			ctx = metadata.AppendToOutgoingContext(ctx, "x-entire-api-auth", apiKey)
59			return invoker(ctx, method, req, reply, cc, opts...)
60		}
61	}
