90	// token up under.
91	func ConnectWithRefresh(dialTarget string, cfg AuthInterceptorConfig, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
92		token, err := getTokenFromKeyring(cfg.KeyringService, cfg.Username)
93		if err != nil {
