130	// RepoResolve translates a human-readable repo reference (bare name,
131	// "owner/repo", or "mirror/github/{owner}/{repo}") to its ULID. Intended
132	// as a one-shot lookup before calling any repo-scoped RPC.
133	//
134	// This is the fast path: the server skips the DHT lookup that would be
135	// needed to populate replicas. Use RepoResolveWithReplicas if you also
136	// want the hosting-node URIs.
137	func (c *Client) RepoResolve(ctx context.Context, repoPath string) (string, error) {
138		ctx, cancel := context.WithTimeout(ctx, callTimeout)
139		defer cancel()
140	
141		resp, err := c.repo.Resolve(ctx, &repopb.ResolveRequest{RepoPath: repoPath})
