150	// brand-new repo) and callers should fall back to whatever they're dialing.
151	func (c *Client) RepoResolveWithReplicas(ctx context.Context, repoPath string) (id string, replicas []string, err error) {
152		ctx, cancel := context.WithTimeout(ctx, callTimeout)
