233	
234	// FileVisitor is invoked once per file in a GetFiles stream. header carries
235	// path/sha/size and any not_found/too_large flag. content is the concatenation
236	// of all data frames for this file; it is empty when the header is not_found
237	// or too_large. Returning an error aborts the stream.
238	type FileVisitor func(header *repopb.FileHeader, content []byte) error
239	
240	// RepoGetFiles drains the streaming GetFiles RPC, invoking visit once per file
241	// with the header and the assembled content bytes. Files arrive in the order
242	// of the request paths.
243	func (c *Client) RepoGetFiles(ctx context.Context, req *repopb.GetFilesRequest, visit FileVisitor) error {
244		ctx, cancel := context.WithTimeout(ctx, callTimeout)
245		defer cancel()
246		stream, err := c.repo.GetFiles(ctx, req)
247		if err != nil {
248			return fmt.Errorf("get files: %w", err)
249		}
250		var (
251			header  *repopb.FileHeader
252			content []byte
253		)
254		flush := func() error {
255			if header == nil {
256				return nil
257			}
258			err := visit(header, content)
259			header = nil
260			content = nil
261			return err
262		}
263		for {
264			msg, err := stream.Recv()
265			if errors.Is(err, io.EOF) {
266				return flush()
267			}
268			if err != nil {
269				return fmt.Errorf("get files: %w", err)
270			}
271			switch frame := msg.GetFrame().(type) {
272			case *repopb.GetFilesResponse_Header:
273				if err := flush(); err != nil {
274					return err
275				}
276				header = frame.Header
277			case *repopb.GetFilesResponse_Data:
278				if header == nil {
279					return errors.New("get files: data frame before header")
280				}
281				content = append(content, frame.Data...)
282			}
283		}
284	}
285	
286	func (c *Client) RepoCompare(ctx context.Context, req *repopb.CompareRequest) (*repopb.CompareResponse, error) {
287		ctx, cancel := context.WithTimeout(ctx, callTimeout)
288		defer cancel()
289		resp, err := c.repo.Compare(ctx, req)
290		if err != nil {
291			return nil, fmt.Errorf("compare: %w", err)
292		}
293		return resp, nil
294	}
295	
296	// RepoDiff drains the streaming Diff RPC into w. Stops after the first chunk
297	// with truncated=true.
298	func (c *Client) RepoDiff(ctx context.Context, req *repopb.DiffRequest, w io.Writer) error {
299		ctx, cancel := context.WithTimeout(ctx, callTimeout)
300		defer cancel()
301		stream, err := c.repo.Diff(ctx, req)
302		if err != nil {
303			return fmt.Errorf("diff: %w", err)
304		}
305		for {
306			chunk, err := stream.Recv()
307			if errors.Is(err, io.EOF) {
308				return nil
309			}
310			if err != nil {
311				return fmt.Errorf("diff: %w", err)
312			}
313			if _, err := w.Write(chunk.GetData()); err != nil {
314				return fmt.Errorf("diff: write output: %w", err)
