package client

import (
	"context"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"time"

	adminpb "github.com/entireio/cli/internal/entiredb/gen/proto/publicapi/admin/v1"
	repopb "github.com/entireio/cli/internal/entiredb/gen/proto/publicapi/repo/v1"
	"github.com/entireio/cli/internal/entiredb/tokenstore"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

const callTimeout = 300 * time.Second

type Client struct {
	repo  repopb.RepoClient
	admin adminpb.AdminClient
	token string
}

type ConnFunc func(c *Client) error

func Connect(host string, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
	return ConnectWithAuth(host, "", clientConnFunc, grpcOpts...)
}

// ConnectWithAPIKey connects using a preshared API key sent via the X-Entire-Api-Auth header.
func ConnectWithAPIKey(host, apiKey string, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
	grpcOpts = append([]grpc.DialOption{
		grpc.WithUnaryInterceptor(apiKeyInterceptor(apiKey)),
	}, grpcOpts...)

	conn, err := grpc.NewClient(host, grpcOpts...)
	if err != nil {
		return fmt.Errorf("connecting to server: %w", err)
	}
	defer func() {
		if closeErr := conn.Close(); closeErr != nil {
			fmt.Printf("Warning: failed to close gRPC connection: %v\n", closeErr)
		}
	}()

	client := &Client{
		repo:  repopb.NewRepoClient(conn),
		admin: adminpb.NewAdminClient(conn),
	}

	return clientConnFunc(client)
}

func apiKeyInterceptor(apiKey string) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		ctx = metadata.AppendToOutgoingContext(ctx, "x-entire-api-auth", apiKey)
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

func ConnectWithAuth(host, token string, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
	grpcOpts = append([]grpc.DialOption{
		grpc.WithUnaryInterceptor(AuthInterceptor(token)),
	}, grpcOpts...)

	conn, err := grpc.NewClient(host, grpcOpts...)
	if err != nil {
		return fmt.Errorf("connecting to server: %w", err)
	}
	defer func() {
		if closeErr := conn.Close(); closeErr != nil {
			fmt.Printf("Warning: failed to close gRPC connection: %v\n", closeErr)
		}
	}()

	client := &Client{
		repo:  repopb.NewRepoClient(conn),
		admin: adminpb.NewAdminClient(conn),
		token: token,
	}

	return clientConnFunc(client)
}

// ConnectWithRefresh connects to the server with automatic token refresh.
// dialTarget is the gRPC host to connect to (e.g. a resolved node).
// cfg.KeyringService is the tokenstore service name to look the access
// token up under.
func ConnectWithRefresh(dialTarget string, cfg AuthInterceptorConfig, clientConnFunc ConnFunc, grpcOpts ...grpc.DialOption) error {
	token, err := getTokenFromKeyring(cfg.KeyringService, cfg.Username)
	if err != nil {
		return fmt.Errorf("getting token: %w", err)
	}

	grpcOpts = append([]grpc.DialOption{
		grpc.WithUnaryInterceptor(AuthInterceptorWithRefresh(cfg, &token)),
	}, grpcOpts...)

	conn, err := grpc.NewClient(dialTarget, grpcOpts...)
	if err != nil {
		return fmt.Errorf("connecting to server: %w", err)
	}
	defer func() {
		if closeErr := conn.Close(); closeErr != nil {
			fmt.Printf("Warning: failed to close gRPC connection: %v\n", closeErr)
		}
	}()

	client := &Client{
		repo:  repopb.NewRepoClient(conn),
		admin: adminpb.NewAdminClient(conn),
		token: token,
	}

	return clientConnFunc(client)
}

func getTokenFromKeyring(keyringService, username string) (string, error) {
	encodedToken, err := tokenstore.Get(keyringService, username)
	if err != nil {
		return "", fmt.Errorf("getting token from keyring: %w", err)
	}
	// Decode the token (may include expiration timestamp)
	token, _ := tokenstore.DecodeTokenWithExpiration(encodedToken)
	return token, nil
}

// RepoResolve translates a human-readable repo reference (bare name,
// "owner/repo", or "mirror/github/{owner}/{repo}") to its ULID. Intended
// as a one-shot lookup before calling any repo-scoped RPC.
//
// This is the fast path: the server skips the DHT lookup that would be
// needed to populate replicas. Use RepoResolveWithReplicas if you also
// want the hosting-node URIs.
func (c *Client) RepoResolve(ctx context.Context, repoPath string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.Resolve(ctx, &repopb.ResolveRequest{RepoPath: repoPath})
	if err != nil {
		return "", fmt.Errorf("resolve repo: %w", err)
	}
	return resp.GetRepoId(), nil
}

// RepoResolveWithReplicas is like RepoResolve but also returns the URIs of
// nodes currently hosting the repo. Replicas may be empty (e.g. for a
// brand-new repo) and callers should fall back to whatever they're dialing.
func (c *Client) RepoResolveWithReplicas(ctx context.Context, repoPath string) (id string, replicas []string, err error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.Resolve(ctx, &repopb.ResolveRequest{
		RepoPath:        repoPath,
		IncludeReplicas: true,
	})
	if err != nil {
		return "", nil, fmt.Errorf("resolve repo: %w", err)
	}
	return resp.GetRepoId(), resp.GetReplicas(), nil
}

func (c *Client) RepoMergeBase(ctx context.Context, repoID, commitA, commitB string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.MergeBase(ctx, &repopb.MergeBaseRequest{
		RepoId:  repoID,
