	if err != nil {
		return "", fmt.Errorf("failed to get merge base: %w", err)
	}
	return resp.GetMergeBase(), nil
}

// RepoMergeBaseFull returns the full MergeBaseResponse including resolved_shas
// for each input ref. Used by Merge/Rebase/Revert commands to snapshot tip
// SHAs before issuing a mutating RPC with expected_*_sha CAS.
func (c *Client) RepoMergeBaseFull(ctx context.Context, req *repopb.MergeBaseRequest) (*repopb.MergeBaseResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.MergeBase(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("failed to get merge base: %w", err)
	}
	return resp, nil
}

func (c *Client) RepoListCommits(ctx context.Context, req *repopb.ListCommitsRequest) (*repopb.ListCommitsResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
