func (c *Client) RepoGetTree(ctx context.Context, req *repopb.GetTreeRequest) (*repopb.GetTreeResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()
	resp, err := c.repo.GetTree(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("get tree: %w", err)
	}
	return resp, nil
