// FileVisitor is invoked once per file in a GetFiles stream. header carries
// path/sha/size and any not_found/too_large flag. content is the concatenation
// of all data frames for this file; it is empty when the header is not_found
// or too_large. Returning an error aborts the stream.
type FileVisitor func(header *repopb.FileHeader, content []byte) error

// RepoGetFiles drains the streaming GetFiles RPC, invoking visit once per file
// with the header and the assembled content bytes. Files arrive in the order
// of the request paths.
func (c *Client) RepoGetFiles(ctx context.Context, req *repopb.GetFilesRequest, visit FileVisitor) error {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()
	stream, err := c.repo.GetFiles(ctx, req)
	if err != nil {
		return fmt.Errorf("get files: %w", err)
	}
	var (
		header  *repopb.FileHeader
		content []byte
	)
	flush := func() error {
		if header == nil {
			return nil
		}
		err := visit(header, content)
		header = nil
		content = nil
		return err
	}
	for {
		msg, err := stream.Recv()
		if errors.Is(err, io.EOF) {
			return flush()
		}
		if err != nil {
			return fmt.Errorf("get files: %w", err)
		}
		switch frame := msg.GetFrame().(type) {
		case *repopb.GetFilesResponse_Header:
			if err := flush(); err != nil {
				return err
			}
			header = frame.Header
		case *repopb.GetFilesResponse_Data:
			if header == nil {
				return errors.New("get files: data frame before header")
			}
			content = append(content, frame.Data...)
		}
	}
}

func (c *Client) RepoCompare(ctx context.Context, req *repopb.CompareRequest) (*repopb.CompareResponse, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()
	resp, err := c.repo.Compare(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("compare: %w", err)
	}
	return resp, nil
}

// RepoDiff drains the streaming Diff RPC into w. Stops after the first chunk
// with truncated=true.
func (c *Client) RepoDiff(ctx context.Context, req *repopb.DiffRequest, w io.Writer) error {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()
	stream, err := c.repo.Diff(ctx, req)
	if err != nil {
		return fmt.Errorf("diff: %w", err)
	}
	for {
		chunk, err := stream.Recv()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("diff: %w", err)
		}
		if _, err := w.Write(chunk.GetData()); err != nil {
			return fmt.Errorf("diff: write output: %w", err)
		}
		if chunk.GetTruncated() {
			return nil
		}
	}
}

// RepoMerge performs a server-side merge of head_ref into base_ref using the
// requested strategy. Conflicts are signalled via MergeResponse.outcome =
// CONFLICT, not as an RPC error.
func (c *Client) RepoMerge(ctx context.Context, req *repopb.MergeRequest) (*repopb.MergeResponse, error) {
