// RepoRebaseStream is a thin wrapper around the server-streaming Rebase RPC
// that exposes each event to the caller (unlike RepoDiff which drains
// internally). The underlying stream closes after the first terminal event
// (RebaseCompleted or RebaseConflict); a subsequent Recv returns io.EOF.
type RepoRebaseStream struct {
	stream grpc.ServerStreamingClient[repopb.RebaseResponse]
}

// Recv returns the next RebaseResponse frame. Returns io.EOF when the stream
// closes cleanly after a terminal event.
func (s *RepoRebaseStream) Recv() (*repopb.RebaseResponse, error) {
	msg, err := s.stream.Recv()
	if err != nil {
		if errors.Is(err, io.EOF) {
			return nil, io.EOF
		}
		return nil, fmt.Errorf("rebase recv: %w", err)
	}
	return msg, nil
}

// Close is a no-op provided for `defer stream.Close()` ergonomics. gRPC
// server-streaming has no client-side Close; callers must cancel the
// context passed to RepoRebase to abort a stream early.
func (s *RepoRebaseStream) Close() error { return nil }

// RepoRebase starts a streaming rebase. The returned RepoRebaseStream exposes
// each event (RebaseStarted, CommitApplied, RebaseConflict, RebaseCompleted)
// so callers can render progress. The caller's ctx controls cancellation; no
// timeout is applied because rebase duration is proportional to commit count.
func (c *Client) RepoRebase(ctx context.Context, req *repopb.RebaseRequest) (*RepoRebaseStream, error) {
	stream, err := c.repo.Rebase(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("rebase: %w", err)
	}
	return &RepoRebaseStream{stream: stream}, nil
}

