// needed to populate replicas. Use RepoResolveWithReplicas if you also
// want the hosting-node URIs.
func (c *Client) RepoResolve(ctx context.Context, repoPath string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.Resolve(ctx, &repopb.ResolveRequest{RepoPath: repoPath})
	if err != nil {
		return "", fmt.Errorf("resolve repo: %w", err)
