func (c *Client) RepoResolveWithReplicas(ctx context.Context, repoPath string) (id string, replicas []string, err error) {
	ctx, cancel := context.WithTimeout(ctx, callTimeout)
	defer cancel()

	resp, err := c.repo.Resolve(ctx, &repopb.ResolveRequest{
