package cli

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"
)

// standaloneRootUse is the standalone entiredb binary's root Use string and
// the prefix that appears in every Example block in this package. The plugin
// tree rewrites that prefix at construction time so help and docs teach the
// dispatched command path instead.
const standaloneRootUse = "entiredb"

func NewRootCmd(cfg Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:           standaloneRootUse,
		Short:         "The Entire developer platform client",
		Long:          `The Entire CLI lets you interact with Entire.io's Git-compatible storage layer.`,
		SilenceErrors: true,
		SilenceUsage:  true,
	}
	cmd.AddCommand(NewRepoCmd(cfg))
	cmd.AddCommand(NewAdminCmd(cfg))
	cmd.AddCommand(NewMirrorCmd(cfg))
	cmd.AddCommand(newAuditCmd(cfg))
	cmd.AddCommand(newDocsCmd())
	return cmd
}

// NewPluginRootCmd builds the command tree for the entire-code plugin
// binary dispatched by the parent `entire` CLI as `entire code`. Surface
// is intentionally trimmed to user-facing read/write operations; admin,
// mirror, and audit live only in the standalone entiredb binary.
//
// Use is set to the dispatched form ("entire code") and
// CommandDisplayNameAnnotation pins the same value so cobra reports
// `entire code repo …` in CommandPath, UseLine, generated docs, and the
// usageArgs error helper. Without that, usage strings would teach
// `entire-code repo …` (the on-disk binary name), which isn't how users
// invoke a kubectl-style plugin.
func NewPluginRootCmd(cfg Config) *cobra.Command {
	const pluginRootUse = "entire code"
	cmd := &cobra.Command{
		Use:   pluginRootUse,
		Short: "Read and rewrite repositories on EntireDB clusters",
		Annotations: map[string]string{
			cobra.CommandDisplayNameAnnotation: pluginRootUse,
		},
		SilenceErrors: true,
		SilenceUsage:  true,
	}
	cmd.AddCommand(NewRepoCmd(cfg))
	cmd.AddCommand(newDocsCmd())
	rebrandExamples(cmd, standaloneRootUse+" ", pluginRootUse+" ")
	return cmd
}

// rebrandExamples rewrites every Example block in cmd's subtree, replacing
// the leading command-path prefix used by the shared subcommand
// constructors. The Example strings in this package are authored for the
// standalone entiredb binary; the plugin root rewrites them so its help
// and `docs` output don't mislead users into typing the wrong command.
func rebrandExamples(cmd *cobra.Command, from, to string) {
	if cmd.Example != "" {
		cmd.Example = strings.ReplaceAll(cmd.Example, from, to)
	}
	for _, c := range cmd.Commands() {
		rebrandExamples(c, from, to)
	}
}

// usageArgs wraps a cobra positional-args validator so that validation errors
// include the command's usage line. SilenceUsage on the root otherwise drops
// the usage hint on arg-count errors.
func usageArgs(v cobra.PositionalArgs) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if err := v(cmd, args); err != nil {
			return fmt.Errorf("%w\nUsage: %s", err, cmd.UseLine())
		}
		return nil
	}
}

