package cli

import (
	"fmt"

	"github.com/spf13/cobra"

	entiredbcli "github.com/entireio/cli/internal/entiredb/cli"
)

// newRepoCmd wires the vendored entiredb `repo` subtree as a hidden
// top-level command, surfaced via `entire labs`. The subtree talks to
// EntireDB clusters for read and rewrite operations (clone, log, diff,
// merge, rebase, revert, …); see labs.go for the labs-visible summary.
//
// Hidden during maturation: the command is functional from `entire repo`
// but does not appear in `entire --help`. Once stable, drop the Hidden
// flag and remove the labs entry in one move.
func newRepoCmd() *cobra.Command {
	cfg, err := entiredbcli.LoadConfig()
	if err != nil {
		// Mirror the lazy-error pattern used by other top-level commands:
		// surface the config-load failure when the user actually invokes
		// `entire repo …`, not at root construction time.
		return &cobra.Command{
			Use:    "repo",
			Short:  "Read and rewrite repositories on EntireDB clusters",
			Hidden: true,
			RunE: func(cmd *cobra.Command, _ []string) error {
				cmd.SilenceUsage = true
				return NewSilentError(fmt.Errorf("entire repo: load config: %w", err))
			},
		}
	}

	cmd := entiredbcli.NewRepoCmd(cfg)
	cmd.Hidden = true
	entiredbcli.RebrandExamples(cmd, "entire ")
	return cmd
}

