// Package cli is the vendored entiredb CLI surface exposing the `repo`
// subtree to the Entire CLI. Originally lifted from entiredb's
// cmd/entiredb/cli package; the standalone-binary root and the admin /
// mirror / audit subtrees were intentionally left behind because the
// Entire CLI ships only the user-facing read/rewrite operations.
//
// Example strings on the repo subtree are still authored against the
// "entiredb" standalone binary's command prefix. RebrandExamples
// rewrites them at construction time so help and docs teach the
// dispatched command path (e.g. "entire repo clone …") instead.
package cli

import (
	"fmt"
	"strings"

	"github.com/spf13/cobra"
)

// upstreamExamplePrefix is the prefix used in every Example block in this
// package, inherited from the standalone entiredb binary. Callers pass it
// to RebrandExamples along with the prefix they want users to see.
const upstreamExamplePrefix = "entiredb "

// RebrandExamples rewrites every Example block in cmd's subtree, replacing
// the upstream "entiredb " prefix with newPrefix. Use this after building
// a subtree with one of the New*Cmd constructors so the help and docs
// output teach the correct command path for the host CLI.
func RebrandExamples(cmd *cobra.Command, newPrefix string) {
	rebrandExamples(cmd, upstreamExamplePrefix, newPrefix)
}

func rebrandExamples(cmd *cobra.Command, from, to string) {
	if cmd.Example != "" {
		cmd.Example = strings.ReplaceAll(cmd.Example, from, to)
	}
	for _, c := range cmd.Commands() {
		rebrandExamples(c, from, to)
	}
}

// usageArgs wraps a cobra positional-args validator so that validation errors
// include the command's usage line. SilenceUsage on the root otherwise drops
// the usage hint on arg-count errors.
func usageArgs(v cobra.PositionalArgs) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if err := v(cmd, args); err != nil {
			return fmt.Errorf("%w\nUsage: %s", err, cmd.UseLine())
		}
		return nil
	}
}

